manialink.script:
#Include "TextLib" as TL

main() {
  declare CMlLabel Counter <=> (Page.GetFirstChild("counter") as CMlLabel);
  declare CMlLabel Button <=> (Page.GetFirstChild("button") as CMlLabel);
  declare Integer Step = TL::ToInteger(Button.DataAttributeGet("step"));
  declare Integer Total = 0;

  while (True) {
    yield;
    foreach (Event in PendingEvents) {
      if (Event.Type == CMlScriptEvent::Type::MouseClick && Event.ControlId == "button") {
        Total += Step;
        Counter.SetText(TL::ToText(Total));
      }
    }
  }
}
